use std::fs

fn is_int(t: string) -> bool {
    let mut digits = 0
    let mut first = true
    for c in t.chars() {
        if first && c == '-' {
            first = false
            continue
        }
        first = false
        if c < '0' || c > '9' {
            return false
        }
        digits += 1
    }
    digits > 0
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split(" ") {
        if t == "" {
            continue
        }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop().unwrap_or(0)
            let a = st.pop().unwrap_or(0)
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
            continue
        }
        if !is_int(t) {
            return "error: token"
        }
        let v: int = t.parse::<int>().unwrap_or(0)
        st.push(v)
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println(eval(line.trim()))
    }
}

